import sys
from functools import lru_cache

K, M = map(int, sys.stdin.read().split())
MOD = 10**9 + 7
if K <= 200000:
    cnt = 0
    for v in range(1, K + 1):
        if sum(int(c) for c in str(v)) % M == 0:
            cnt += 1
    print(cnt % MOD)
else:
    # independent check for big K: exact counts per digit sum (no remainders), then group by sum % M
    ds = [int(c) for c in str(K)]

    @lru_cache(maxsize=None)
    def ways(pos, s, tight):
        # numbers (leading zeros allowed) built from positions pos.. with running digit sum s
        if pos == len(ds):
            return 1 if s % M == 0 else 0
        top = ds[pos] if tight else 9
        return sum(ways(pos + 1, s + x, tight and x == top) for x in range(top + 1))

    print((ways(0, 0, True) - 1) % MOD)

